INSERT OR IGNORE INTO products (slug, title, vendor, product_type, tags, description_html, price_amount, compare_at_amount, currency, available, status, published_at, updated_at) VALUES ('etos-star-micronics-sp742-lan', 'Star Micronics SP742 LAN', 'eatOS - Restaurant management made simple', NULL, '[]', '<p>Impact Kitchen Printer</p>
<p><span>Built specifically to work in environments where heat and humidity can erode the type on the kitchen order, the SP742 is an ideal </span>kitchen printing solution<span>. This fast, two-color printer offers crisp, easy to read type for quick viewing, clamshell design for easy paper loading and an embedded power supply for space efficiency.</span></p>', 349, NULL, 'USD', 1, 'published', '2021-08-20T08:42:35-04:00', '2026-08-29T07:43:11-04:00');
