INSERT OR IGNORE INTO products (slug, title, vendor, product_type, tags, description_html, price_amount, compare_at_amount, currency, available, status, published_at, updated_at) VALUES ('eatos-star-micronics-tsp654ii-sticky-printer-lan', 'Star Micronics TSP654II Sticky Printer LAN', 'eatOS - Restaurant management made simple', NULL, '[]', '<span>The TSP654IISK liner-free label printer is designed to work with liner-free labeling applications and is ideal for creating food labels and more. Repositionable thermal labels can stick to virtually any surface, and can be removed easily and reapplied leaving behind no residue. The liner-free labels are an alternative to using silicone-lined labels or tape. New to the TSP654IISK is the addition of the Taken Sensor, which enables the printer to hold print jobs until the first print job is taken. </span>', 339, NULL, 'USD', 1, 'published', '2021-08-20T08:23:32-04:00', '2026-08-29T07:43:11-04:00');
